 public static void clickButton(String prefix){var screen=net.minecraft.client.Minecraft.getInstance().screen;var button=screen.children().stream().filter(w->w instanceof net.minecraft.client.gui.components.Button b&&b.getMessage().getString().startsWith(prefix)).map(w->(net.minecraft.client.gui.components.Button)w).findFirst().orElseThrow();check(screen.mouseClicked(button.getX()+button.getWidth()/2.0,button.getY()+button.getHeight()/2.0,0),"Mouse click delivered: "+prefix);screen.mouseReleased(button.getX()+button.getWidth()/2.0,button.getY()+button.getHeight()/2.0,0);}
 // Windows clipboard listeners can briefly hold the clipboard after rapid fixture writes.
 private static void fixtureClipboard(String text)throws Exception{var keyboard=net.minecraft.client.Minecraft.getInstance().keyboardHandler;for(int i=0;i<20;i++){keyboard.setClipboard(text);Thread.sleep(25);if(keyboard.getClipboard().equals(text))return;}throw new AssertionError("Windows clipboard remained unavailable for fixture setup");}
