   editor.setValue("local value = 12\nprint(value)\n");double x=editor.getX()+4+mc.font.width("local "),y=editor.getY()+6;check(screen.mouseClicked(x,y,0),"Click inside code is delivered");screen.mouseReleased(x,y,0);check(field.cursor()==6,"Mouse places cursor at the clicked character");screen.charTyped('X',0);check(editor.getValue().startsWith("local Xvalue"),"Typing inserts at the clicked position");
